  assert.equal(r2.value.lines[1].discountPercent, 0);
});

test('invoiceTotals calculates correctly with tier discounts', () => {
  // C-001 (gold tier = 5%)
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }
    ]
  });

  const totals = invoiceTotals(r.value);
  // Subtotal: 5 * 8500 = 42500
  // Discount: 42500 * 5% = 2125
  // Total: 42500 - 2125 = 40375
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.total, 40375);
});

