    ]
  });

  const text = renderInvoiceText(r.value);

  assert.ok(text.includes('12.5% discount'), 'Should show decimal discount percentage');
});

test('renderInvoiceText does not show discount for 0% discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 }
    ]
  });

  const text = renderInvoiceText(r.value);

  assert.equal(text.includes('0% discount'), false, 'Should not show 0% discount');
});

test('renderInvoiceText shows total discount summary', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'STICKER', qty: 100, discountPercent: 5 }
    ]
  });

  const text = renderInvoiceText(r.value);

  // Total discount: 4250 + 250 = 4500
  assert.ok(text.includes('Discount:'), 'Should show discount summary line');
  assert.ok(text.includes('€45.00') || text.includes('€4,500.00'), 'Should show total discount amount');
});

test('renderInvoiceText does not show discount summary when no discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }
    ]
  });

  const text = renderInvoiceText(r.value);

  const discountLine = text.split('\n').find((line) => line.startsWith('Discount:'));
  assert.equal(discountLine, undefined, 'Should not show discount summary when there are no discounts');
});

test('renderInvoiceText calculates total after discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 }
    ]
  });

  const text = renderInvoiceText(r.value);

  // Subtotal: 42500, Discount: 4250, Total: 38250
  assert.ok(text.includes('Total: €382.50'), 'Should show total after discount');
});

